        usageSteps: { ru: ["Нанесите на ватный диск после очищения кожи.", "Протрите лицо и шею лёгкими движениями, не смывать.", "Используйте утром и вечером перед сывороткой или кремом."], kz: ["Теріні тазартқаннан кейін мақта дискіге тамызыңыз.", "Бет пен мойынды жеңіл қимылдармен сүртіңіз, шаймаңыз.", "Сарысу немесе крем жағар алдында таңертең және кешке қолданыңыз."] },
